import json,io
d=json.load(io.open('config/config.json',encoding='utf-8'))
def leaves(o):
    if isinstance(o,dict): return sum(leaves(v) for v in o.values())
    if isinstance(o,list): return sum(leaves(v) for v in o) if o else 0
    return 1
def nodes(o):
    if isinstance(o,dict): return len(o) + sum(nodes(v) for v in o.values())
    if isinstance(o,list): return sum(nodes(v) for v in o)
    return 0
tot=0
print(f'{\"域\":22s}{\"叶值\":>6s}{\"节点\":>6s}')
for k,v in d.items():
    tot+=leaves(v)
    print(f'{k:22s}{leaves(v):6d}{nodes(v):6d}')
print('-'*34)
print(f'{\"合计（叶值）\":18s}{tot:6d}')
"

